{
  "status": "SUPPORTED",
  "task_summary": "Identify fastening parts from storage, attach them to a marked spot on the workbench, and leave the tool on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "Surface where the fastening takes place and where the tool is left.",
        "required_count": 1
      , "binding_policy": "REUSABLE"
      , "candidate_categories": ["table", "desk", "surface"]
      , "required_properties": ["stable", "flat"]
      },
      {
        "id": "fastening_location",
        "entity_kind": "FIXED_TARGET",
        "function": "Specific spot on the workbench that needs to be fastened.",
        "required_count": 1
      , "binding_policy": "DISTINCT"
      , "candidate_categories": ["hole", "joint", "assembly_point"]
      , "required_properties": ["receives_fastener"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "Instrument used to apply the fastening.",
        "required_count": 1
      , "binding_policy": "REUSABLE"
      , "candidate_categories": ["screwdriver", "wrench", "tool"]
      , "required_properties": ["can_drive_fastener"]
      },
      {
        "id": "fastening_component",
        "entity_kind": "OBJECT",
        "function": "Physical part (screw, nut, etc.) that secures the fastening.",
        "required_count": 1
      , "binding_policy": "REUSABLE"
      , "candidate_categories": ["screw", "bolt", "nut", "washer"]
      , "required_properties": ["fits_fastening_location"]
      },
      {
        "id": "storage_container",
        "entity_kind": "OBJECT",
        "function": "Enclosed space containing the required tools and components.",
        "required_count": 1
      , "binding_policy": "SHARED"
      , "candidate_categories": ["drawer", "cabinet", "box"]
      , "required_properties": ["contains_items", "openable"]
      }
    ],
    "functional_relations": [
      {
        "id": "part_attaches_to_location",
        "relation": "fastening_component must be attached to fastening_location",
        "participant_roles": ["fastening_component", "fastening_location"]
      , "required": true
      },
      {
        "id": "tool_actuates_location",
        "relation": "fastening_tool must act upon fastening_location",
        "participant_roles": ["fastening_tool", "fastening_location"]
      , "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "search_for_items",
        "operation": "Search storage_container to find fastening_tool and fastening_component",
        "participant_roles": ["storage_container", "fastening_tool", "fastening_component"]
      , "operation_count": 1
      },
      {
        "id": "fasten_items",
        "operation": "Use fastening_tool to attach fastening_component to fastening_location",
        "participant_roles": ["fastening_tool", "fastening_component", "fastening_location"]
      , "operation_count": 1
      },
      {
        "id": "place_tool",
        "operation": "Place fastening_tool onto workbench",
        "participant_roles": ["fastening_tool", "workbench"]
      , "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "workbench": [
        {"label": "wooden table", "visual_description": "Large wooden surface with drawers underneath"}
      ],
      "fastening_location": [
        {"label": "area near tray", "visual_description": "Grey tray with yellow blocks sits on the table surface"}
      ],
      "storage_container": [
        {"label": "blue cabinet", "visual_description": "Tall blue box-like object on the table"},
        {"label": "left drawer", "visual_description": "Blue drawer with handle under the left side of the table"},
        {"label": "right drawer", "visual_description": "Blue drawer with handle under the right side of the table"}
      ]
    },
    "inspectable_regions": [
      {"id": "blue_cabinet", "label": "blue cabinet on table", "visual_description": "Closed door suggests contents are hidden inside", "reason": "Likely holds tools or components"},
      {"id": "left_drawer", "label": "left drawer under table", "visual_description": "Handle indicates it opens, contents unknown", "reason": "Likely holds tools or components"},
      {"id": "right_drawer", "label": "right drawer under table", "visual_description": "Handle indicates it opens, contents unknown", "reason": "Likely holds tools or components"}
    ],
    "inspection_order": [
      "blue_cabinet",
      "left_drawer",
      "right_drawer"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
